/**
 * Generated by scripts/generate-icons.mjs from assets/mark.svg: icon-192.png 192px, icon-512.png 512px, icon-maskable-512.png 512px, apple-touch-icon-180.png 180px.
 * Regenerate with `pnpm --dir plugins/@dshfiles/pwa icons` instead of editing.
 */
export const iconAssets = {
  'icon-192.png':
    '',
  'icon-512.png':
    '',
  'icon-maskable-512.png':
    '',
  'apple-touch-icon-180.png':
    '',
} as const

export type IconName = keyof typeof iconAssets

export const iconNames: readonly IconName[] = ['icon-192.png', 'icon-512.png', 'icon-maskable-512.png', 'apple-touch-icon-180.png']

export const isIconName = (value: string): value is IconName => Object.hasOwn(iconAssets, value)
